async function loadProfiles(db, userIds) {
  if (!Array.isArray(userIds)) {
    throw new TypeError('userIds must be an array');
  }
  if (userIds.length === 0) {
    return [];
  }
  if (userIds.length > MAX_PROFILE_IDS_PER_BATCH) {
    throw new RangeError(
      `userIds length (${userIds.length}) exceeds maximum batch size of ${MAX_PROFILE_IDS_PER_BATCH}`
    );
  }

  const result = await db.query(
    'SELECT user_id, display_name, email, created_at FROM profiles WHERE user_id = ANY($1)',
    [userIds]
  );
  return result.rows;
}
```

